import { test, expect } from '@playwright/test';

test.describe('Form Autocomplete Attributes - Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form-autocomplete');
  });

  test('should set correct autocomplete attributes for input fields', async ({ page }) => {
    // Intercept the API call for autocomplete suggestions
    await page.route('**/api/autocomplete', (route) => {
      route.continue();
    });

    // Fill in the first input field using getByLabel
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('test@example.com');

    // Verify the autocomplete attribute is set
    const emailInputAttribute = await emailInput.evaluate((el) => el.getAttribute('data-autocomplete'));
    expect(emailInputAttribute).toBe('email');

    // Verify the input has the correct role
    const emailInputRole = await emailInput.evaluate((el) => el.getAttribute('aria-role'));
    expect(emailInputRole).toBe('textbox');

    // Verify the input has the correct aria-autocomplete attribute
    const emailInputAriaAutocomplete = await emailInput.evaluate((el) => el.getAttribute('aria-autocomplete'));
    expect(emailInputAriaAutocomplete).toBe('list');

    // Fill in the second input field using getByLabel
    const firstNameInput = page.getByLabel('First Name');
    await firstNameInput.fill('John');

    // Verify the autocomplete attribute is set
    const firstNameInputAttribute = await firstNameInput.evaluate((el) => el.getAttribute('data-autocomplete'));
    expect(firstNameInputAttribute).toBe('text');

    // Verify the input has the correct role
    const firstNameInputRole = await firstNameInput.evaluate((el) => el.getAttribute('aria-role'));
    expect(firstNameInputRole).toBe('textbox');

    // Verify the input has the correct aria-autocomplete attribute
    const firstNameInputAriaAutocomplete = await firstNameInput.evaluate((el) => el.getAttribute('aria-autocomplete'));
    expect(firstNameInputAriaAutocomplete).toBe('list');

    // Verify the form is accessible using getByRole
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeVisible();
  });

  test('should handle invalid input and display appropriate error messages', async ({ page }) => {
    // Fill in the first input field with invalid data
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('invalid-email');

    // Verify the input has the correct aria-invalid attribute
    const emailInputAriaInvalid = await emailInput.evaluate((el) => el.getAttribute('aria-invalid'));
    expect(emailInputAriaInvalid).toBe('true');

    // Verify the input has the correct aria-describedby attribute
    const emailInputAriaDescribedBy = await emailInput.evaluate((el) => el.getAttribute('aria-describedby'));
    expect(emailInputAriaDescribedBy).toBeDefined();

    // Verify the error message is displayed
    const errorMessage = page.getByText(/Please enter a valid email address/i);
    await expect(errorMessage).toBeVisible();

    // Verify the submit button is disabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();

    // Verify the form has the correct tabindex
    const emailInputTabIndex = await emailInput.evaluate((el) => el.getAttribute('tabindex'));
    expect(emailInputTabIndex).toBe('0');
  });
});
